#!/usr/bin/env node
/**
 * buchbinder-index — Build or update the lore/knowledge/outline/draft index
 * and verify ONNX reranker functionality.
 *
 * Thin CLI wrapper around src/lib/index-builder.mjs. Installed by the
 * per-project installer into .opencode/tools/lib/scripts/ alongside
 * lore-query.mjs, and exposed as the `buchbinder-index` bin entry.
 *
 * After a successful index build, this command warms and smoke-tests the
 * included in-process ONNX cross-encoder reranker (onnxruntime via
 * @huggingface/transformers, default Xenova/bge-reranker-base) so
 * `refresh-index` covers reranker functionality as well as embeddings.
 *
 * Usage:
 *   node bin/build-lore-index.mjs [project-root] [--force] [--quiet]
 *   node bin/build-lore-index.mjs --status [project-root]
 *
 * If project-root is omitted, defaults to the current working directory.
 *
 * Exits:
 *   0  — success (index built; reranker warmup reported, non-fatal if unavailable)
 *   1  — status mode, no index found
 *   2  — index build failed (e.g. the ONNX embedder could not be loaded)
 */

import { resolve } from 'path'
import { ensureDeps } from './lib/bootstrap.mjs'

// Resolve modules relative to this script (bin/build-lore-index.mjs → ../src/lib/*)
const here = new URL(import.meta.url).pathname
const indexBuilderPath = resolve(here, '../../src/lib/index-builder.mjs')
const rerankerPath = resolve(here, '../../src/lib/reranker.mjs')
// Bootstrap package deps first so this runs from a bare clone (no node_modules).
await ensureDeps()
const { buildIndex, printStatus } = await import(indexBuilderPath)

const args = process.argv.slice(2)
let projectRoot = process.cwd()
let statusOnly = false
let force = false
let quiet = false

for (let i = 0; i < args.length; i++) {
    const a = args[i]
    if (a === '--status') statusOnly = true
    else if (a === '--force') force = true
    else if (a === '--quiet') quiet = true
    else if (a === '--help' || a === '-h') {
        console.log('Usage: node bin/build-lore-index.mjs [project-root] [--force] [--quiet]')
        console.log('       node bin/build-lore-index.mjs --status [project-root]')
        console.log('')
        console.log('Builds/updates the semantic lore index and warms/verifies the ONNX reranker.')
        process.exit(0)
    } else if (!a.startsWith('--')) {
        projectRoot = resolve(a)
    }
}

async function warmAndVerifyReranker() {
    try {
        const { getReranker, rerankDocuments, RERANK_MODEL, isRerankDisabled } = await import(rerankerPath)
        if (typeof isRerankDisabled === 'function' && isRerankDisabled()) {
            if (!quiet) console.log('[buchbinder-index] Reranker: skipped (RERANK_DISABLED=1)')
            return { ok: false, skipped: true }
        }
        await getReranker()
        const ranked = await rerankDocuments(
            'creative values and quality baseline',
            [
                'Core values and quality baseline for the manuscript.',
                'Chapter 7: the protagonist buys bread at the market.',
                'Thematic statement, non-negotiables, and style principles.',
            ],
        )
        if (!quiet) {
            console.log(`[buchbinder-index] Reranker: ready (${RERANK_MODEL})`)
            const top = ranked[0]
            if (top) console.log(`[buchbinder-index] Reranker smoke-test: top score=${top.score.toFixed(4)} idx=${top.index}`)
        }
        return { ok: true }
    } catch (err) {
        if (!quiet) {
            console.warn(`[buchbinder-index] Reranker: unavailable (${err.message})`)
            console.warn('[buchbinder-index] Retrieval will degrade gracefully without reranking; re-fetch models when possible (node bin/fetch-models.mjs --only reranker).')
        }
        return { ok: false, error: err.message }
    }
}

if (statusOnly) {
    printStatus(projectRoot)
    process.exit(0)
}

try {
    const summary = await buildIndex(projectRoot, { force, quiet })
    if (!quiet) {
        console.log('')
        console.log(`  Index ready: ${summary.indexPath}`)
        console.log(`  ${summary.chunksTotal} chunks from ${summary.sourcesTotal} sources`)
        console.log(`  Build time:  ${(summary.durationMs / 1000).toFixed(1)}s`)
    }

    // Include reranker functionality (ONNX cross-encoder / onnxruntime) as part of refresh-index.
    await warmAndVerifyReranker()

    process.exit(0)
} catch (err) {
    console.error(`[buchbinder-index] Build failed: ${err.message}`)
    process.exit(2)
}

#!/usr/bin/env node
/**
 * buchbinder-models — prefetch the local ONNX models.
 *
 * Downloads (once, into the shared model cache) the three Transformers.js
 * models Buchbinder uses, so first use at query time is instant and offline:
 *
 *   embedder    Xenova/bge-base-en-v1.5        (~110 MB q8)
 *   reranker    Xenova/bge-reranker-base       (~280 MB q8)
 *   classifier  Xenova/nli-deberta-v3-xsmall   (~70 MB q8)
 *
 * The installer and refresh run this automatically. It is tolerant: a failure
 * to fetch any model is a warning, not an error — retrieval degrades gracefully.
 *
 * Usage:
 *   node bin/fetch-models.mjs [--only embedder,reranker,classifier] [--quiet]
 *
 * Honours ONNX_OFFLINE=1 (skips remote fetches), ONNX_CACHE_DIR, and the
 * model-id env vars (ONNX_EMBED_MODEL, RERANK_MODEL, CLASSIFIER_MODEL).
 */

import { fileURLToPath } from 'url'
import { ensureDeps } from './lib/bootstrap.mjs'
import { resolveModelCacheDir, isOnnxOffline, sharedModelCacheDir } from '../src/lib/onnx-runtime.mjs'

const args = process.argv.slice(2)
let only = null
let quiet = false
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--only') only = (args[++i] || '').split(',').map(s => s.trim())
  else if (args[i] === '--quiet') quiet = true
}

const log = (...a) => { if (!quiet) console.log(...a) }

async function main() {
  // The embedder/reranker/classifier modules load @huggingface/transformers
  // lazily; make sure the package deps exist before touching them so this
  // works from a bare clone (no node_modules) too.
  await ensureDeps()
  const { getOnnxEmbedder, ONNX_EMBED_MODEL } = await import('../src/lib/embedder.mjs')
  const { getReranker, RERANK_MODEL } = await import('../src/lib/reranker.mjs')
  const { getNliModel, CLASSIFIER_MODEL } = await import('../src/lib/classifier.mjs')

  const targets = [
    { name: 'embedder', model: ONNX_EMBED_MODEL, load: () => getOnnxEmbedder() },
    { name: 'reranker', model: RERANK_MODEL, load: () => getReranker() },
    { name: 'classifier', model: CLASSIFIER_MODEL, load: () => getNliModel() },
  ].filter(t => !only || only.includes(t.name))

  log(`[models] cache: ${sharedModelCacheDir()}`)
  if (isOnnxOffline()) {
    log('[models] ONNX_OFFLINE=1 — skipping downloads (using any cached models only)')
  }

  let failures = 0
  for (const t of targets) {
    const cached = resolveModelCacheDir(t.model)
    log(`[models] ${t.name}: ${t.model}`)
    try {
      await t.load()
      log(`[models]   ✓ ready (${cached})`)
    } catch (err) {
      failures++
      log(`[models]   ✗ unavailable: ${err.message}`)
    }
  }

  if (failures > 0) {
    log(`[models] ${failures} model(s) unavailable — retrieval will degrade gracefully until they can be fetched.`)
  } else {
    log('[models] all models ready.')
  }
  // Never fail the install because a model could not be fetched.
  process.exit(0)
}

if (process.argv[1] && import.meta.url === `file://${fileURLToPath(new URL(import.meta.url))}`) {
  main().catch(err => {
    console.error(`[models] ${err.message}`)
    process.exit(0)
  })
}

/**
 * Buchbinder — Token Efficiency & API Reduction Hooks (OpenCode v2 server plugin)
 *
 * Registered as the server part of the Buchbinder plugin package. These hooks
 * reduce API calls and token waste without reducing functionality.
 *
 * Migrated from the V1 hook-return-object pattern to the OpenCode v2 spec:
 *   - Plain default export `{ id, setup(ctx) }` server plugin entrypoint
 *   - Hooks registered via `ctx.session.hook(...)` / `ctx.tool.hook(...)`
 *
 * Hook mapping (V1 -> V2):
 *   1. experimental.session.compacting      -> ctx.session.hook("compaction")
 *   2. experimental.chat.system.transform   -> ctx.session.hook("context")  [system]
 *   3. experimental.chat.messages.transform -> ctx.session.hook("context")  [messages]
 *   4. tool.execute.after                   -> ctx.tool.hook("execute.after")
 *   5. chat.params                          -> ctx.session.hook("context")  [options]
 *   6. experimental.compaction.autocontinue -> no direct V2 hook (re-evaluated;
 *                                              phase state gates compaction work)
 *   7. tool.execute.before                  -> ctx.tool.hook("execute.before")
 */

import { readFileSync, existsSync, writeFileSync, mkdirSync } from 'fs'
import { join, dirname } from 'path'

// ─── State file paths ──────────────────────────────────────────────────────
const STATE_DIR = '.opencode/state'
const PHASE_STATE_FILE = 'phase-state.json'
const TOOL_CACHE_FILE = 'tool-cache.json'
const MAX_CACHED_TOOLS = 200

// ─── Phase token budgets ──────────────────────────────────────────────────
const PHASE_BUDGETS = {
  guided:     { maxTokens: 2048,  temperature: 0.3 },
  verify:     { maxTokens: 2048,  temperature: 0.2 },
  cite:       { maxTokens: 1024,  temperature: 0.2 },
  publish:    { maxTokens: 2048,  temperature: 0.2 },
  review:     { maxTokens: 4096,  temperature: 0.3 },
  outline:    { maxTokens: 8192,  temperature: 0.5 },
  draft:      { maxTokens: 16384, temperature: 0.7 },
  critique:   { maxTokens: 8192,  temperature: 0.4 },
  revise:     { maxTokens: 8192,  temperature: 0.5 },
  edit:       { maxTokens: 8192,  temperature: 0.3 },
  research:   { maxTokens: 4096,  temperature: 0.4 },
  specify:    { maxTokens: 4096,  temperature: 0.4 },
  clarify:    { maxTokens: 4096,  temperature: 0.3 },
  'task-manager': { maxTokens: 4096, temperature: 0.3 },
  cycle:      { maxTokens: 8192,  temperature: 0.5 },
  'pacing-audit': { maxTokens: 4096, temperature: 0.3 },
  'hook-review':  { maxTokens: 4096, temperature: 0.3 },
  'read-through': { maxTokens: 8192, temperature: 0.3 },
  series:     { maxTokens: 4096,  temperature: 0.3 },
  track:      { maxTokens: 4096,  temperature: 0.3 },
  timeline:   { maxTokens: 4096,  temperature: 0.3 },
  meta:       { maxTokens: 2048,  temperature: 0.3 },
  drafter:    { maxTokens: 8192,  temperature: 0.7 },
  resume:     { maxTokens: 2048,  temperature: 0.3 },
}

// ─── Helpers ───────────────────────────────────────────────────────────────

function statePath(projectRoot, file) {
  return join(projectRoot, STATE_DIR, file)
}

function ensureStateDir(p) {
  const d = dirname(p)
  if (!existsSync(d)) mkdirSync(d, { recursive: true })
}

function readJson(p, fallback) {
  try {
    if (existsSync(p)) return JSON.parse(readFileSync(p, 'utf-8'))
  } catch { /* ignore */ }
  return fallback
}

function writeJson(p, data) {
  ensureStateDir(p)
  writeFileSync(p, JSON.stringify(data, null, 2), 'utf-8')
}

/** Extract the buchbinder phase from text, if any. */
function detectPhase(text) {
  if (!text || typeof text !== 'string') return null
  const m = text.match(/\/buchbinder(?:-router)?\s+(\S+)/)
  return m ? m[1] : null
}

/** Best-effort text extraction from v2 message/context shapes. */
function extractText(value) {
  if (!value) return ''
  if (typeof value === 'string') return value
  if (Array.isArray(value)) return value.map(extractText).join(' ')
  if (typeof value === 'object') {
    if (typeof value.text === 'string') return value.text
    if (typeof value.content === 'string') return value.content
    if (Array.isArray(value.content)) return extractText(value.content)
    if (Array.isArray(value.parts)) return extractText(value.parts)
  }
  return ''
}

function phaseFromContext(event, projectRoot) {
  // Prefer persisted phase state (set by the workflow), fall back to scanning
  // the request messages for a /buchbinder command.
  const state = readJson(statePath(projectRoot, PHASE_STATE_FILE), {})
  if (state.currentPhase) return state.currentPhase
  const msgs = event?.messages
  if (Array.isArray(msgs)) {
    for (let i = msgs.length - 1; i >= 0; i--) {
      const p = detectPhase(extractText(msgs[i]))
      if (p) return p
    }
  }
  return null
}

function phaseStateSummary(projectRoot) {
  const phaseState = readJson(statePath(projectRoot, PHASE_STATE_FILE), {})
  if (!phaseState.currentPhase) return null
  return `
## Buchbinder Phase State (preserved across compaction)

Current phase: ${phaseState.currentPhase || 'none'}
Current chapter: ${phaseState.currentChapter || 'none'}
Gate results: ${phaseState.gateSummary || 'none'}
Last action: ${phaseState.lastAction || 'none'}
Next step: ${phaseState.nextStep || 'Run /buchbinder guided to assess state'}
`.trim()
}

/** System parts that carry OpenCode/buchbinder instructions worth keeping. */
function isEssentialSystemPart(part, phase) {
  const text = typeof part === 'string' ? part : extractText(part)
  if (!text) return true
  if (text.includes('AGENTS.md') || text.includes('karpathy') || text.includes('shell_strategy')) return true
  if (text.includes('file-operations') || text.includes('security') || text.includes('completion-guardrail')) return true
  if (phase && text.includes(phase)) return true
  if (text.includes('buchbinder') || text.includes('Buchbinder')) return true
  return false
}

/** Files/tools that are safe to cache (deterministic reads). */
const CACHEABLE_READS = new Set([
  'read', 'grep', 'glob', 'list_mcp_resources', 'list_mcp_resource_templates',
])

// ─── Plugin (OpenCode v2 server part) ─────────────────────────────────────

export default {
  id: 'buchbinder-hooks',
  async setup(ctx) {
    // V2 context exposes the plugin's load location. Fall back to cwd for
    // compatibility with runtimes that may not populate every field.
    const projectRoot = (ctx && ctx.location && ctx.location.directory) || process.cwd()
    const sp = (file) => statePath(projectRoot, file)

    // ── 1. Preserve phase state across compaction ──
    await ctx.session.hook('compaction', (event) => {
      const summary = phaseStateSummary(projectRoot)
      if (!summary) return
      const part = { type: 'text', text: summary }
      if (Array.isArray(event.system)) event.system.push(part)
      else if (Array.isArray(event.messages)) event.messages.push({ role: 'system', content: summary })
    })

    // ── 2 & 3 & 5. Agent-loop context shaping ──
    await ctx.session.hook('context', (event) => {
      const phase = phaseFromContext(event, projectRoot)

      // (2) Keep only essential + phase-relevant system instructions.
      if (phase && Array.isArray(event.system)) {
        event.system = event.system.filter((s) => isEssentialSystemPart(s, phase))
      }

      // (3) Prune stale messages — keep the first and the most recent window.
      if (Array.isArray(event.messages)) {
        const MAX_MESSAGES = 30
        if (event.messages.length > MAX_MESSAGES) {
          const first = event.messages[0]
          const recent = event.messages.slice(-MAX_MESSAGES)
          event.messages = [first, ...recent]
        }
      }

      // (5) Reduce output tokens / temperature for non-creative phases.
      if (phase) {
        const budget = PHASE_BUDGETS[phase]
        if (budget) {
          event.options ??= {}
          event.options.maxTokens = budget.maxTokens
          event.options.temperature = budget.temperature
        }
      }
    })

    // Also apply phase-aware trimming to transient generate requests.
    await ctx.session.hook('generate', (event) => {
      const phase = phaseFromContext(event, projectRoot)
      if (phase && Array.isArray(event.system)) {
        event.system = event.system.filter((s) => isEssentialSystemPart(s, phase))
      }
      if (phase) {
        const budget = PHASE_BUDGETS[phase]
        if (budget) {
          event.options ??= {}
          event.options.maxTokens = budget.maxTokens
          event.options.temperature = budget.temperature
        }
      }
    })

    // ── 4. Cache deterministic tool outputs ──
    await ctx.tool.hook('execute.after', (event) => {
      const toolName = event.tool || event.name || ''
      if (!CACHEABLE_READS.has(toolName)) return

      const result = event.result ?? event.output
      if (event.status && event.status !== 'completed') return
      if (!result) return

      const args = event.input ?? event.args ?? {}
      const cacheKey = `${toolName}:${JSON.stringify(args)}`
      const cache = readJson(sp(TOOL_CACHE_FILE), {})

      cache[cacheKey] = {
        output: typeof result === 'string' ? result : (result.content ?? result.output ?? result),
        title: result.title ?? toolName,
      }

      const keys = Object.keys(cache)
      if (keys.length > MAX_CACHED_TOOLS) {
        for (const k of keys.slice(0, keys.length - MAX_CACHED_TOOLS)) delete cache[k]
      }

      writeJson(sp(TOOL_CACHE_FILE), cache)
    })

    // ── 7. Redundant re-read guard (cache-aware) ──
    await ctx.tool.hook('execute.before', (event) => {
      const toolName = event.tool || event.name || ''
      if (toolName !== 'read') return
      const args = event.input ?? event.args ?? {}
      if (!args.filePath && !args.path) return
      const cacheKey = `read:${JSON.stringify(args)}`
      const cache = readJson(sp(TOOL_CACHE_FILE), {})
      void cache[cacheKey]
    })

    // Note (V1: experimental.compaction.autocontinue): no direct V2 equivalent.
  },
}

/**
 * Buchbinder — Token Efficiency & API Reduction Hooks (OpenCode v2 server plugin)
 *
 * Registered as the server part of the Buchbinder plugin package. These hooks
 * reduce API calls and token waste without reducing functionality.
 *
 * Migrated from the V1 hook-return-object pattern to the OpenCode v2 spec:
 *   - `Plugin.define({ id, setup(ctx) })` entrypoint (`@opencode/plugin`)
 *   - Hooks registered via `ctx.session.hook(...)` / `ctx.tool.hook(...)`
 *
 * Hook mapping (V1 -> V2):
 *   1. experimental.session.compacting      -> ctx.session.hook("compaction")
 *   2. experimental.chat.system.transform   -> ctx.session.hook("context")  [system]
 *   3. experimental.chat.messages.transform -> ctx.session.hook("context")  [messages]
 *   4. tool.execute.after                   -> ctx.tool.hook("execute.after")
 *   5. chat.params                          -> ctx.session.hook("context")  [options]
 *   6. experimental.compaction.autocontinue -> no direct V2 hook (re-evaluated;
 *                                              phase state gates compaction work)
 *   7. tool.execute.before                  -> ctx.tool.hook("execute.before")
 */

import { readFileSync, existsSync, writeFileSync, mkdirSync } from 'fs'
import { join, dirname } from 'path'

// ─── State file paths ──────────────────────────────────────────────────────
const STATE_DIR = '.opencode/state'
const PHASE_STATE_FILE = 'phase-state.json'
const TOOL_CACHE_FILE = 'tool-cache.json'
const MAX_CACHED_TOOLS = 200

// ─── Phase token budgets ──────────────────────────────────────────────────
const PHASE_BUDGETS: Record<string, { maxTokens: number; temperature: number }> = {
  guided:     { maxTokens: 2048,  temperature: 0.3 },
  verify:     { maxTokens: 2048,  temperature: 0.2 },
  cite:       { maxTokens: 1024,  temperature: 0.2 },
  publish:    { maxTokens: 2048,  temperature: 0.2 },
  review:     { maxTokens: 4096,  temperature: 0.3 },
  outline:    { maxTokens: 8192,  temperature: 0.5 },
  draft:      { maxTokens: 16384, temperature: 0.7 },
  critique:   { maxTokens: 8192,  temperature: 0.4 },
  revise:     { maxTokens: 8192,  temperature: 0.5 },
  edit:       { maxTokens: 8192,  temperature: 0.3 },
  research:   { maxTokens: 4096,  temperature: 0.4 },
  specify:    { maxTokens: 4096,  temperature: 0.4 },
  clarify:    { maxTokens: 4096,  temperature: 0.3 },
  'task-manager': { maxTokens: 4096, temperature: 0.3 },
  cycle:      { maxTokens: 8192,  temperature: 0.5 },
  'pacing-audit': { maxTokens: 4096, temperature: 0.3 },
  'hook-review':  { maxTokens: 4096, temperature: 0.3 },
  'read-through': { maxTokens: 8192, temperature: 0.3 },
  series:     { maxTokens: 4096,  temperature: 0.3 },
  track:      { maxTokens: 4096,  temperature: 0.3 },
  timeline:   { maxTokens: 4096,  temperature: 0.3 },
  meta:       { maxTokens: 2048,  temperature: 0.3 },
  drafter:    { maxTokens: 8192,  temperature: 0.7 },
  resume:     { maxTokens: 2048,  temperature: 0.3 },
}

// ─── Helpers ───────────────────────────────────────────────────────────────

function statePath(projectRoot: string, file: string): string {
  return join(projectRoot, STATE_DIR, file)
}

function ensureStateDir(p: string) {
  const d = dirname(p)
  if (!existsSync(d)) mkdirSync(d, { recursive: true })
}

function readJson<T>(p: string, fallback: T): T {
  try {
    if (existsSync(p)) return JSON.parse(readFileSync(p, 'utf-8'))
  } catch { /* ignore */ }
  return fallback
}

function writeJson(p: string, data: any) {
  ensureStateDir(p)
  writeFileSync(p, JSON.stringify(data, null, 2), 'utf-8')
}

interface PhaseState {
  currentPhase?: string
  currentChapter?: string
  gateSummary?: string
  lastAction?: string
  nextStep?: string
}

/** Extract the buchbinder phase from text, if any. */
function detectPhase(text: string | undefined | null): string | null {
  if (!text || typeof text !== 'string') return null
  const m = text.match(/\/buchbinder(?:-router)?\s+(\S+)/)
  return m ? m[1] : null
}

/** Best-effort text extraction from v2 message/context shapes. */
function extractText(value: any): string {
  if (!value) return ''
  if (typeof value === 'string') return value
  if (Array.isArray(value)) return value.map(extractText).join(' ')
  if (typeof value === 'object') {
    if (typeof value.text === 'string') return value.text
    if (typeof value.content === 'string') return value.content
    if (Array.isArray(value.content)) return extractText(value.content)
    if (Array.isArray(value.parts)) return extractText(value.parts)
  }
  return ''
}

function phaseFromContext(event: any, projectRoot: string): string | null {
  // Prefer persisted phase state (set by the workflow), fall back to scanning
  // the request messages for a /buchbinder command.
  const state = readJson<PhaseState>(statePath(projectRoot, PHASE_STATE_FILE), {})
  if (state.currentPhase) return state.currentPhase
  const msgs = event?.messages
  if (Array.isArray(msgs)) {
    for (let i = msgs.length - 1; i >= 0; i--) {
      const p = detectPhase(extractText(msgs[i]))
      if (p) return p
    }
  }
  return null
}

function phaseStateSummary(projectRoot: string): string | null {
  const phaseState = readJson<PhaseState>(statePath(projectRoot, PHASE_STATE_FILE), {})
  if (!phaseState.currentPhase) return null
  return `
## Buchbinder Phase State (preserved across compaction)

Current phase: ${phaseState.currentPhase || 'none'}
Current chapter: ${phaseState.currentChapter || 'none'}
Gate results: ${phaseState.gateSummary || 'none'}
Last action: ${phaseState.lastAction || 'none'}
Next step: ${phaseState.nextStep || 'Run /buchbinder guided to assess state'}
`.trim()
}

/** System parts that carry OpenCode/buchbinder instructions worth keeping. */
function isEssentialSystemPart(part: any, phase: string): boolean {
  const text = typeof part === 'string' ? part : extractText(part)
  if (!text) return true
  if (text.includes('AGENTS.md') || text.includes('karpathy') || text.includes('shell_strategy')) return true
  if (text.includes('file-operations') || text.includes('security') || text.includes('completion-guardrail')) return true
  if (phase && text.includes(phase)) return true
  if (text.includes('buchbinder') || text.includes('Buchbinder')) return true
  return false
}

/** Files/tools that are safe to cache (deterministic reads). */
const CACHEABLE_READS = new Set([
  'read', 'grep', 'glob', 'list_mcp_resources', 'list_mcp_resource_templates',
])

// ─── Plugin (OpenCode v2 server part) ─────────────────────────────────────

export default {
  id: 'buchbinder-hooks',
  async setup(ctx: any) {
    // V2 context exposes the plugin's load location. Fall back to cwd for
    // compatibility with runtimes that may not populate every field.
    const projectRoot: string = (ctx as any).location?.directory || process.cwd()
    const sp = (file: string) => statePath(projectRoot, file)

    // ── 1. Preserve phase state across compaction ──
    // V1: experimental.session.compacting (pushed to output.context).
    // V2: session "compaction" hook. Inject phase state into the compaction
    // request's system parts so the summary retains workflow position. We do
    // NOT set event.result (that would skip the model summary entirely).
    await ctx.session.hook('compaction', (event: any) => {
      const summary = phaseStateSummary(projectRoot)
      if (!summary) return
      const part = { type: 'text', text: summary }
      if (Array.isArray(event.system)) event.system.push(part)
      else if (Array.isArray(event.messages)) event.messages.push({ role: 'system', content: summary })
    })

    // ── 2 & 3 & 5. Agent-loop context shaping ──
    // V1: experimental.chat.system.transform, experimental.chat.messages.transform,
    //     chat.params. V2: session "context" hook (agent loop) edits system,
    //     messages, and options for the outgoing model call only.
    await ctx.session.hook('context', (event: any) => {
      const phase = phaseFromContext(event, projectRoot)

      // (2) Keep only essential + phase-relevant system instructions.
      if (phase && Array.isArray(event.system)) {
        event.system = event.system.filter((s: any) => isEssentialSystemPart(s, phase))
      }

      // (3) Prune stale messages — keep the first and the most recent window.
      if (Array.isArray(event.messages)) {
        const MAX_MESSAGES = 30
        if (event.messages.length > MAX_MESSAGES) {
          const first = event.messages[0]
          const recent = event.messages.slice(-MAX_MESSAGES)
          event.messages = [first, ...recent]
        }
      }

      // (5) Reduce output tokens / temperature for non-creative phases.
      if (phase) {
        const budget = PHASE_BUDGETS[phase]
        if (budget) {
          event.options ??= {}
          event.options.maxTokens = budget.maxTokens
          event.options.temperature = budget.temperature
        }
      }
    })

    // Also apply phase-aware trimming to transient generate requests.
    await ctx.session.hook('generate', (event: any) => {
      const phase = phaseFromContext(event, projectRoot)
      if (phase && Array.isArray(event.system)) {
        event.system = event.system.filter((s: any) => isEssentialSystemPart(s, phase))
      }
      if (phase) {
        const budget = PHASE_BUDGETS[phase]
        if (budget) {
          event.options ??= {}
          event.options.maxTokens = budget.maxTokens
          event.options.temperature = budget.temperature
        }
      }
    })

    // ── 4. Cache deterministic tool outputs ──
    await ctx.tool.hook('execute.after', (event: any) => {
      const toolName: string = event.tool || event.name || ''
      if (!CACHEABLE_READS.has(toolName)) return

      // V2 event shape: completed results carry `result`; tolerate V1-like
      // `output` for compatibility across minor SDK revisions.
      const result = event.result ?? event.output
      if (event.status && event.status !== 'completed') return
      if (!result) return

      const args = event.input ?? event.args ?? {}
      const cacheKey = `${toolName}:${JSON.stringify(args)}`
      const cache = readJson<Record<string, any>>(sp(TOOL_CACHE_FILE), {})

      cache[cacheKey] = {
        output: typeof result === 'string' ? result : (result.content ?? result.output ?? result),
        title: result.title ?? toolName,
      }

      const keys = Object.keys(cache)
      if (keys.length > MAX_CACHED_TOOLS) {
        for (const k of keys.slice(0, keys.length - MAX_CACHED_TOOLS)) delete cache[k]
      }

      writeJson(sp(TOOL_CACHE_FILE), cache)
    })

    // ── 7. Redundant re-read guard (cache-aware) ──
    // V2 has no supported way to short-circuit tool execution from a hook, so
    // we keep the read cheap by maintaining the cache (hook 4) and leaving a
    // marker point for future cache-hit injection if the SDK adds it.
    await ctx.tool.hook('execute.before', (event: any) => {
      const toolName: string = event.tool || event.name || ''
      if (toolName !== 'read') return
      const args = event.input ?? event.args ?? {}
      if (!args.filePath && !args.path) return
      const cacheKey = `read:${JSON.stringify(args)}`
      const cache = readJson<Record<string, any>>(sp(TOOL_CACHE_FILE), {})
      // Cache hit exists: the read will proceed (v2 hook cannot return a cached
      // result), but the after-hook keeps the cache warm for the session.
      void cache[cacheKey]
    })

    // Note (V1: experimental.compaction.autocontinue): no direct V2 equivalent.
    // The migration guide requires re-evaluating this behavior. Buchbinder phases
    // report results and stop by design; phase state is preserved by hook (1) so
    // the user — not an auto-continue — decides the next step.
  },
}

# Artifact Template

Use this structure for a `## [Artifact Name]` section in `./book/knowledge/artifacts.md`.

```markdown
## {Artifact Name}

- **Type:** {object | weapon | document | technology | relic | symbol | resource | other}
- **Status:** {active | lost | destroyed | hidden | transferred | unknown}
- **Owner:** {character or faction}
- **Location:** {location}
- **Related:** {other artifacts, systems}

### Description
What the artifact looks like and how readers recognize it.

### Function
What it can do, what it cannot do, and what it costs.

### History
Origin, prior owners, and story-relevant events.

### Current State
Current owner, location, condition, and unresolved risks.
```

Cross-reference the owner and location. Artifacts do not take progressions — track an artifact's changes through the continuity state checks.

# Faction Template

Use this structure for a `## [Faction Name]` section in `./book/knowledge/factions.md`.

```markdown
## {Faction Name}

- **Type:** {family | guild | government | military | religion | company | community | criminal | other}
- **Status:** {active | hidden | declining | defeated | disbanded | unknown}
- **Members:** {character names}
- **Locations:** {location names}
- **Related:** {other factions, systems}

### Purpose
What this faction wants and why it exists.

### Power Base
Resources, influence, territory, legitimacy, secrets, rituals, or leverage.

### Members
Important members and their roles.

### Conflicts
Internal divisions and external opposition.
```

Verify named members exist in `character-profiles.md` and cross-reference back. Record later changes to a faction as **Progressions**, not by editing the opening values.

# Location Template

Use this structure for a `## [Location Name]` section in `./book/knowledge/locations.md`.

```markdown
## {Location Name}

- **Type:** {city, district, wilderness, submerged-ruin, …}
- **Region:** {parent region}
- **Population:** {number or estimate}
- **Controlled by:** {character or faction}
- **Status:** {thriving, declining, strained, exposed, unknown}
- **Setting:** {interior | exterior | both}
- **Pronunciation:** {optional, e.g. KEL-ah-mar}
- **Notable characters:** {character names}
- **Routes:**
  - to: {location} — {hours} {mode}
- **Related:** {other locations, factions, systems}

### Description
What the location looks, sounds, smells, and feels like. First impressions for someone arriving. Key sensory details that make it distinct.

### History
How the location came to be and key events that happened here. Only history relevant to the story.

### Culture & Customs
The people who live here, their way of life, traditions, social norms. What makes this place culturally distinct.

### Notable Features
Specific landmarks, buildings, natural features, or points of interest within the location. Things characters would interact with.

### Current State
What the location is like at the time the story opens. Political situation, recent events, tensions, opportunities.
```

`Type` and `Status` are free-form descriptive strings. `Setting` (interior/exterior/both) is optional. A route is two-way unless the other location declares its own; the continuity scan checks dated scenes against its hours (see `maps-and-routes.md`). Record later changes to a location as **Progressions**, not by editing the opening values.
